import { Ledger } from "./ledger.ts";

export class InsufficientFundsError extends Error {
  constructor(requested: number, available: number) {
    super(`Cannot withdraw ${requested}: only ${available} available`);
    this.name = "InsufficientFundsError";
  }
}

export class Account {
  private ledger = new Ledger();

  deposit(amount: number): void {
    this.ledger.record(amount, "credit");
  }

  /** Withdraw funds. Throws InsufficientFundsError if the balance is too low. */
  withdraw(amount: number): number {
    const available = this.ledger.balance();
    if (amount > available) {
      throw new InsufficientFundsError(amount, available);
    }
    this.ledger.record(-amount, "debit");
    return amount;
  }
}

