export type EntryKind = "credit" | "debit";

export interface Entry {
  amount: number;
  kind: EntryKind;
}

export class Ledger {
  private entries: Entry[] = [];

  /** Record an entry. `kind` is now required to classify the movement. */
  record(amount: number, kind: EntryKind): void {
    this.entries.push({ amount, kind });
  }

  balance(): number {
    return this.entries.reduce((sum, e) => sum + e.amount, 0);
  }
}
